<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {NAlert,NButton} from 'naive-ui';
import {api,ApiError,errorMessage} from '../../shared/api';
import type {ExecutionThinkingLevel} from './thinking-options';
import EmployeeThinkingLevel from './EmployeeThinkingLevel.vue';import ModelSelector from './ModelSelector.vue';import ActionBar from '../../shared/ui/ActionBar.vue';
const props=defineProps<{base:string;disabled?:boolean}>(),emit=defineEmits<{busyChanged:[boolean];dirtyChanged:[boolean];saved:[ExecutionThinkingLevel];sessionExpired:[]}>();
type Setting={selectedProfileId:string|null;executionThinkingLevel:ExecutionThinkingLevel;revision:string};
const profiles=ref<{id:string;name:string;modelId:string;enabled:boolean}[]>([]),selection=ref<string|null>(null),thinking=ref<ExecutionThinkingLevel>('medium'),original=ref<Setting|null>(null),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),uncertain=ref(false);
const dirty=computed(()=>!!original.value&&(selection.value!==original.value.selectedProfileId||thinking.value!==original.value.executionThinkingLevel));
watch(dirty,v=>emit('dirtyChanged',v),{flush:'sync'});watch(saving,v=>emit('busyChanged',v),{flush:'sync'});const controller=new AbortController();
async function load(preserve=false){loading.value=true;error.value='';try{const [catalog,current]=await Promise.all([api<{profiles:typeof profiles.value}>(props.base.split('/entities/')[0]+'/model-profiles',controller.signal),api<Setting>(props.base+'/model-settings',controller.signal)]);if(controller.signal.aborted)return;profiles.value=catalog.profiles;if(!preserve){selection.value=current.selectedProfileId;thinking.value=current.executionThinkingLevel;}else notice.value=current.selectedProfileId===selection.value&&current.executionThinkingLevel===thinking.value?'已核对：当前设置与你的选择一致。':'已读取当前设置，你的修改已保留，请核对后保存。';original.value=current;uncertain.value=false;}catch(c){if(!controller.signal.aborted){error.value=errorMessage(c);if(c instanceof ApiError&&c.status===401)emit('sessionExpired');}}finally{loading.value=false;}}
async function save(){if(saving.value||!original.value||props.disabled||uncertain.value)return;saving.value=true;error.value='';notice.value='';try{const r=await api<Setting>(props.base+'/model-settings',controller.signal,{profileId:selection.value,executionThinkingLevel:thinking.value,expectedRevision:original.value.revision},'PUT');if(controller.signal.aborted)return;original.value=r;emit('saved',thinking.value);notice.value='已保存。';}catch(c){if(!controller.signal.aborted){uncertain.value=!(c instanceof ApiError)||c.status>=500;error.value=errorMessage(c);if(c instanceof ApiError&&c.status===401)emit('sessionExpired');}}finally{saving.value=false;}}
function cancel(){if(!original.value)return;selection.value=original.value.selectedProfileId;thinking.value=original.value.executionThinkingLevel;}
void load();onUnmounted(()=>{controller.abort();emit('busyChanged',false);emit('dirtyChanged',false);});
</script><template><section class="model-settings selection-form form-section" aria-label="模型与思考强度"><div class="form-section-heading"><h3>模型与思考强度</h3></div><NAlert v-if="uncertain" type="warning">模型保存结果尚未确认，请先核对；你的选择已保留，暂不要重复保存。</NAlert><NAlert v-if="error" type="error">{{error}}</NAlert><NAlert v-if="notice" type="info">{{notice}}</NAlert><p v-if="loading" role="status">正在读取模型配置…</p><template v-if="original"><p class="field-note">当前来源：{{original.selectedProfileId?'员工选择的共享模型':'继承工作区默认模型'}}</p><ModelSelector v-model:value="selection" :profiles="profiles" :disabled="saving||disabled||uncertain"/><EmployeeThinkingLevel v-model:value="thinking" :disabled="saving||disabled||uncertain"/><p v-if="!profiles.length" class="field-note">暂无共享模型。请到资源库配置后返回；没有有效模型暂不能对话、执行或摘要。</p><ActionBar><NButton :type="dirty?'primary':'default'" :loading="saving" :disabled="saving||disabled||uncertain||!dirty" aria-label="保存模型与思考强度" @click="save">保存</NButton><NButton :disabled="saving" aria-label="取消模型修改" @click="cancel">取消</NButton><NButton :disabled="saving||loading" @click="load(true)">读取服务器配置并核对</NButton></ActionBar></template><NButton v-else-if="!loading" @click="load()">重新读取模型配置</NButton></section></template>

<style scoped>.model-settings{display:grid;gap:var(--id-space-4);margin-top:0}.model-settings :deep(.employee-thinking){max-width:24rem}.model-settings :deep(.n-form-item){margin:0}.model-settings p{margin:0}</style>
